const msg = $input.first().json.body.messages[0];
const sender = msg.from;
const phone  = sender.split('@')[0];
const text   = msg.text?.body || msg.caption || '[media]';

const workflowData = $getWorkflowStaticData('global');
if (!workflowData.conversations) workflowData.conversations = {};

const history = workflowData.conversations[phone] || [];
history.push({ role: 'user', content: text });
if (history.length > 20) history.splice(0, history.length - 20);
workflowData.conversations[phone] = history;

return [{ json: { phone, text, history, sender } }];

