const claudeResponse = $input.first().json;
const assistantText  = claudeResponse.content[0].text;
const phone  = $('Extraer mensaje e historial').first().json.phone;
const sender = $('Extraer mensaje e historial').first().json.sender;

// Guardar respuesta en historial
const workflowData = $getWorkflowStaticData('global');
const history = workflowData.conversations[phone] || [];
history.push({ role: 'assistant', content: assistantText });
workflowData.conversations[phone] = history;

// Detectar lead calificado
const isLead   = assistantText.includes('[LEAD:');
const leadMatch = assistantText.match(/\[LEAD: (.+?)\]/);
const leadRaw  = leadMatch ? leadMatch[1] : null;

// Parsear campos del lead
let leadData = {};
if (leadRaw) {
  leadRaw.split(',').forEach(part => {
    const [k, v] = part.split('=').map(s => s.trim());
    if (k && v) leadData[k] = v;
  });
}

// Limpiar texto para enviar al usuario
const cleanText = assistantText.replace(/\[LEAD:.*?\]/g, '').trim();

return [{ json: { phone, sender, responseText: cleanText, isLead, leadData } }];

